import heapq


def _validate(lengths, max_batch):
    if isinstance(max_batch, bool) or not isinstance(max_batch, int) or max_batch <= 0:
        raise ValueError("max_batch must be a positive int")
    for n in lengths:
        if isinstance(n, bool) or not isinstance(n, int) or n <= 0:
            raise ValueError("every output length must be a positive int")


def static_batching(lengths, max_batch):
    """FIFO groups of max_batch; a group runs for its longest request and
    every member is returned when the group ends. Time unit = one decode step."""
    _validate(lengths, max_batch)
    done, t = [], 0
    for i in range(0, len(lengths), max_batch):
        group = lengths[i:i + max_batch]
        t += max(group)
        done.extend([t] * len(group))
    return {"total_steps": t, "completion": done}


def continuous_batching(lengths, max_batch):
    """FIFO admission at step boundaries: a request enters the moment a slot
    frees and leaves after exactly its own number of steps."""
    _validate(lengths, max_batch)
    active = []            # min-heap of finish times of running requests
    done, last_start = [], 0
    for n in lengths:
        start = 0
        if len(active) >= max_batch:
            start = heapq.heappop(active)
        start = max(start, last_start)   # keep FIFO order of admissions
        last_start = start
        finish = start + n
        heapq.heappush(active, finish)
        done.append(finish)
    return {"total_steps": max(done) if done else 0, "completion": done}
